// Which API list each tool reads. Only what the agent filled in goes into the query.
const MAX_PAGE_SIZE = 100;
const MY_LIST_SIZE = 20;
const LOCAL_TIME = /^([01]\d|2[0-4]):[0-5]\d$/;
const input = $json;
const optional = (value) => String(value ?? '').trim();

if (input.tool === 'find_free_times') {
  const query = { date: optional(input.date), free: true, size: MAX_PAGE_SIZE };
  if (Number(input.venueId) > 0) query.venueId = Number(input.venueId);
  if (optional(input.type)) query.type = optional(input.type);
  if (LOCAL_TIME.test(optional(input.from))) query.from = optional(input.from);
  if (LOCAL_TIME.test(optional(input.to))) query.to = optional(input.to);
  return { json: { path: 'availability', query } };
}
if (input.tool === 'my_bookings') {
  return { json: { path: 'bookings', query: { from: new Date().toISOString(), size: MY_LIST_SIZE, sort: 'startsAt,asc' } } };
}
if (input.tool === 'my_memberships') {
  return { json: { path: 'memberships', query: { size: MY_LIST_SIZE, sort: 'startsOn,desc' } } };
}
throw new Error('Unknown tool: ' + input.tool);

// What the agent reads: Sri Lankan times and "LKR 2,500", never UTC or cents.
const call = $('Tool Call').item.json;
const names = JSON.parse(call.names);
const DEFAULT_TIME_ZONE = 'Asia/Colombo';
const BOOKING_WORDS = {
  AWAITING_PAYMENT: 'waiting for payment',
  AWAITING_CHECK: 'receipt sent, the venue is checking it',
  CONFIRMED: 'confirmed',
  EXPIRED: 'expired, as it was not paid in time',
  CANCELLED: 'cancelled',
};
const MEMBERSHIP_WORDS = { ...BOOKING_WORDS, ACTIVE: 'active', ENDED: 'ended' };

const money = (m) => m.currency + ' ' + (m.amount / 100).toLocaleString('en-US', { maximumFractionDigits: 2 });
const zoneOf = (venueId) => names.venues[venueId]?.timeZone ?? DEFAULT_TIME_ZONE;
const time = (iso, timeZone) => new Date(iso).toLocaleTimeString('en-GB', { timeZone, hour: 'numeric', minute: '2-digit', hour12: true });
const day = (iso, timeZone) => new Date(iso).toLocaleDateString('en-GB', { timeZone, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
const localDay = (isoDate) => day(isoDate + 'T12:00:00Z', 'UTC');
const venueName = (venueId) => names.venues[venueId]?.name ?? 'a venue that is closed for now';
const resourceName = (resourceId) => {
  const resource = names.resources[resourceId];
  return resource ? resource.name + ' at ' + venueName(resource.venueId) : 'a resource no longer listed';
};
const toPay = (item) =>
  item.status === 'AWAITING_PAYMENT' && item.expiresAt
    ? ': send ' + money(item.amountDue) + ' by ' + time(item.expiresAt, zoneOf(item.venueId)) + ' on ' + day(item.expiresAt, zoneOf(item.venueId))
    : item.balance.amount > 0 && (item.status === 'CONFIRMED' || item.status === 'ACTIVE')
      ? ', ' + money(item.balance) + ' still to pay at the venue'
      : '';

function answer() {
  if ($json.error || !$json.body) return 'The check failed. Tell the customer you can\'t check right now.';
  const { statusCode, body } = $json;
  if (statusCode >= 400) {
    const why = (body.errors ?? []).map((e) => e.field + ': ' + e.message).join('; ') || body.message;
    return 'The check was refused (' + why + ').' + (statusCode >= 500 ? " Tell the customer you can't check right now." : '');
  }
  const { content, totalElements } = body.data;

  if (call.tool === 'find_free_times') {
    const date = localDay(call.date);
    if (content.length === 0) return 'Nothing is free on ' + date + " for this search. Don't say why: it may be booked, closed or past.";
    const byResource = new Map();
    for (const slot of content) byResource.set(slot.resourceId, [...(byResource.get(slot.resourceId) ?? []), slot]);
    const lines = ['Free start times on ' + date + ' (each price is for one slot from that time):'];
    for (const [resourceId, slots] of byResource) {
      const resource = names.resources[resourceId];
      lines.push(resourceName(resourceId) + (resource ? ', ' + resource.slotMinutes + '-minute slots:' : ':'));
      const byPrice = new Map();
      for (const slot of slots) {
        const price = money(slot.price);
        byPrice.set(price, [...(byPrice.get(price) ?? []), time(slot.startsAt, zoneOf(resource?.venueId))]);
      }
      for (const [price, times] of byPrice) lines.push('• ' + price + ': ' + times.join(', '));
    }
    if (totalElements > content.length) {
      lines.push('Only the first ' + content.length + ' of ' + totalElements + ' free start times are listed. Ask about a narrower time or one venue for the rest.');
    }
    return lines.join('\n');
  }

  if (call.tool === 'my_bookings') {
    if (content.length === 0) return 'The customer has no upcoming bookings.';
    const lines = content.map((b) => {
      const zone = zoneOf(b.venueId);
      return '• bookingId ' + b.id + ': ' + resourceName(b.resourceId) + ', ' + day(b.startsAt, zone) + ', ' + time(b.startsAt, zone) + ' to ' + time(b.endsAt, zone) +
        ', ' + money(b.price) + ': ' + BOOKING_WORDS[b.status] + toPay(b);
    });
    return ['The customer\'s upcoming bookings:', ...lines].join('\n');
  }

  if (content.length === 0) return 'The customer has no memberships.';
  const lines = content.map((m) =>
    '• ' + m.planName + ' at ' + venueName(m.venueId) + ', ' + localDay(m.startsOn) + ' to ' + localDay(m.endsOn) +
      ', ' + money(m.price) + ': ' + MEMBERSHIP_WORDS[m.status] + toPay(m));
  return ['The customer\'s memberships, newest first:', ...lines].join('\n');
}

return { json: { result: answer() } };

// offer_booking: reads what the agent asked for, before asking the API about it.
const LOCAL_DATE = /^\d{4}-\d{2}-\d{2}$/;
const LOCAL_TIME = /^([01]\d|2[0-3]):[0-5]\d$/;
const MAX_SLOTS = 96;
const MINUTES_PER_DAY = 24 * 60;

const call = $json;
const names = JSON.parse(call.names);
const resourceId = Number(call.resourceId);
const date = String(call.date ?? '').trim();
const startTime = String(call.startTime ?? '').trim().padStart(5, '0');
const slots = Number(call.slots) || 1;
const customerName = String(call.customerName ?? '').trim().replace(/\s+/g, ' ');

const refuse = (why) => ({ json: { ok: false, result: 'No Chat Offer was made: ' + why } });

if (!names.resources[resourceId]) return refuse('there is no resource ' + call.resourceId + '. Use a resourceId from "What you know".');
if (!LOCAL_DATE.test(date)) return refuse('the date must be YYYY-MM-DD.');
if (!LOCAL_TIME.test(startTime)) return refuse('startTime must be HH:MM on a 24-hour clock, such as 19:00.');
if (!Number.isInteger(slots) || slots < 1 || slots > MAX_SLOTS) return refuse('slots must be a whole number from 1.');
if (call.customerKnown !== 'true' && call.customerKnown !== true && customerName === '') {
  return refuse('the customer is new. Ask for their name first, then call offer_booking again with customerName.');
}

// The API takes start times from `from` and before `to`; one minute later picks out exactly this one.
const [hours, minutes] = startTime.split(':').map(Number);
const next = Math.min(hours * 60 + minutes + 1, MINUTES_PER_DAY);
const to = next === MINUTES_PER_DAY ? '24:00' : String(Math.floor(next / 60)).padStart(2, '0') + ':' + String(next % 60).padStart(2, '0');

return {
  json: {
    ok: true,
    resourceId,
    date,
    startTime,
    slots,
    customerName,
    query: { resourceId, date, from: startTime, to, slots },
  },
};

// offer_booking: the exact booking and price from the API, as a Chat Offer, or why it can't be offered.
const CENTS_PER_RUPEE = 100;
const FULL_AMOUNT_PERCENT = 100;
const FOOTER_LIMIT = 60;

const call = $('Tool Call').item.json;
const request = $('Check Booking Request').item.json;
const names = JSON.parse(call.names);
const resource = names.resources[request.resourceId];
const venue = names.venues[resource.venueId];

const money = (m) => m.currency + ' ' + (m.amount / CENTS_PER_RUPEE).toLocaleString('en-US', { maximumFractionDigits: 2 });
const time = (iso) => new Date(iso).toLocaleTimeString('en-GB', { timeZone: venue.timeZone, hour: 'numeric', minute: '2-digit', hour12: true });
const day = (iso) => new Date(iso).toLocaleDateString('en-GB', { timeZone: venue.timeZone, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
const shortDay = (iso) => new Date(iso).toLocaleDateString('en-GB', { timeZone: venue.timeZone, weekday: 'short', day: 'numeric', month: 'short' });
const durationOf = (minutes) => (minutes % 60 === 0 ? minutes / 60 + ' hour' + (minutes === 60 ? '' : 's') : minutes + ' minutes');
const refuse = (why) => ({ json: { ok: false, result: 'No Chat Offer was made: ' + why } });
const failed = (reply) => reply.error || !reply.body || reply.statusCode >= 400;

const slotReply = $('Ask Slot').item.json;
if (failed(slotReply)) {
  const why = slotReply.body?.message ?? 'the check failed';
  return refuse(why + '. If it is a technical failure, say you can\'t check right now and give the way to reach a person.');
}
const slot = slotReply.body.data.content[0];
if (!slot) {
  return refuse(
    request.startTime + ' on ' + request.date + ' is not a start time of ' + resource.name +
      ': it may be off its Start Interval, outside opening hours, in the past, closed that day or too far ahead. Use find_free_times.',
  );
}
if (!slot.free) {
  return refuse(
    resource.name + ' is not free for all ' + durationOf(request.slots * resource.slotMinutes) + ' from ' + time(slot.startsAt) +
      ' on ' + day(slot.startsAt) + '. Use find_free_times to offer other times.',
  );
}

// D-07: one booking waiting for payment per customer, except at Pay at Venue venues.
const waitingReply = $('Ask Waiting').item.json;
const waiting = failed(waitingReply) ? [] : waitingReply.body.data.content;
if (!venue.payAtVenue && waiting.length > 0) {
  const other = waiting[0];
  const otherResource = names.resources[other.resourceId];
  return refuse(
    'the customer already has a booking waiting for payment (bookingId ' + other.id + ', ' + (otherResource?.name ?? 'a resource') +
      ', ' + day(other.startsAt) + ' at ' + time(other.startsAt) + '). Only one can wait for payment at a time: they pay for that one first, or cancel it (offer_cancel).',
  );
}

const amountDue = venue.payAtVenue
  ? 0
  : Math.ceil((slot.price.amount * venue.advancePercent) / (FULL_AMOUNT_PERCENT * CENTS_PER_RUPEE)) * CENTS_PER_RUPEE;
const paying = venue.payAtVenue
  ? 'Pay at Venue: it is confirmed straight away and paid at the venue.'
  : 'After the yes, ' + money({ amount: amountDue, currency: slot.price.currency }) +
    (venue.advancePercent === FULL_AMOUNT_PERCENT ? '' : ' (the Advance)') + ' is due by bank transfer within ' +
    durationOf(venue.paymentTimeLimitMinutes) + ', or the booking expires.';
const summary = resource.name + ' at ' + venue.name + ', ' + day(slot.startsAt) + ', ' + time(slot.startsAt) + ' to ' + time(slot.endsAt) + ', ' + money(slot.price);
const footer = (shortDay(slot.startsAt) + ' · ' + time(slot.startsAt) + '–' + time(slot.endsAt) + ' · ' + money(slot.price)).slice(0, FOOTER_LIMIT);

return {
  json: {
    ok: true,
    kind: 'book',
    details: {
      resourceId: request.resourceId,
      startsAt: slot.startsAt,
      slots: request.slots,
      price: slot.price,
      customerName: request.customerName || null,
      summary,
      footer,
    },
    result:
      'Chat Offer made, waiting for the customer\'s yes: ' + summary + '. ' + paying +
      ' Now ask the customer, in their language, to confirm exactly this. Put the yes label first and the no label second in "choices"; they become the Yes and No buttons.',
  },
};

// offer_cancel: one of the customer's own bookings as a Chat Offer to cancel it, or why it can't be.
const CENTS_PER_RUPEE = 100;
const MS_PER_HOUR = 60 * 60 * 1000;
const FOOTER_LIMIT = 60;
const DEFAULT_TIME_ZONE = 'Asia/Colombo';

const call = $('Tool Call').item.json;
const names = JSON.parse(call.names);
const reply = $json;
const refuse = (why) => ({ json: { ok: false, result: 'No Chat Offer was made: ' + why } });

if (reply.error || !reply.body) return refuse("the check failed. Say you can't check right now and give the way to reach a person.");
if (reply.statusCode === 404 || reply.statusCode === 400) {
  return refuse('the customer has no booking ' + call.bookingId + '. Use my_bookings to find the right bookingId.');
}
if (reply.statusCode >= 400) return refuse((reply.body.message ?? 'the check failed') + '.');

const booking = reply.body.data;
const resource = names.resources[booking.resourceId];
const venue = names.venues[booking.venueId];
const timeZone = venue?.timeZone ?? DEFAULT_TIME_ZONE;
const reach = venue ? 'call ' + venue.name + ' on ' + venue.phone : 'contact the venue';
const money = (m) => m.currency + ' ' + (m.amount / CENTS_PER_RUPEE).toLocaleString('en-US', { maximumFractionDigits: 2 });
const time = (iso) => new Date(iso).toLocaleTimeString('en-GB', { timeZone, hour: 'numeric', minute: '2-digit', hour12: true });
const day = (iso) => new Date(iso).toLocaleDateString('en-GB', { timeZone, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
const shortDay = (iso) => new Date(iso).toLocaleDateString('en-GB', { timeZone, weekday: 'short', day: 'numeric', month: 'short' });

const what = (resource?.name ?? 'a resource') + ' at ' + (venue?.name ?? 'a venue') + ', ' + day(booking.startsAt) + ', ' +
  time(booking.startsAt) + ' to ' + time(booking.endsAt) + ', ' + money(booking.price);
const now = Date.now();
const startsAt = new Date(booking.startsAt).getTime();

if (booking.status === 'CANCELLED' || booking.status === 'EXPIRED') {
  return refuse('that booking (' + what + ') is already ' + booking.status.toLowerCase() + '.');
}
if (booking.status === 'AWAITING_CHECK') {
  return refuse('the venue is checking the Transfer Receipt of that booking (' + what + '), so only the venue can cancel it now: ' + reach + '.');
}
if (startsAt <= now) return refuse('that booking (' + what + ') has already started.');
// BKG-06: a booking still waiting for payment can be cancelled any time; a confirmed one only before the cut-off.
if (booking.status === 'CONFIRMED' && now > startsAt - booking.cancellationCutOffHours * MS_PER_HOUR) {
  return refuse(
    "it's too late to cancel that booking (" + what + ') in this chat: the venue takes cancellations up to ' +
      booking.cancellationCutOffHours + ' hours before the start. Tell the customer kindly and ' + reach + '.',
  );
}

const refund = booking.paid.amount > 0
  ? ' The customer paid ' + money(booking.paid) + ' for it; a refund is up to the venue, so tell them to ' + reach + ' about it.'
  : '';
const footer = ('Cancel · ' + shortDay(booking.startsAt) + ' · ' + time(booking.startsAt) + '–' + time(booking.endsAt)).slice(0, FOOTER_LIMIT);

return {
  json: {
    ok: true,
    kind: 'cancel',
    details: { bookingId: booking.id, summary: 'cancel ' + what, footer },
    result:
      'Chat Offer made, waiting for the customer\'s yes: cancel ' + what + '.' + refund +
      ' Now ask the customer, in their language, to confirm cancelling exactly this. Put the yes label first and the no label second in "choices"; they become the Yes and No buttons.',
  },
};
